export function getAllProducts(): Product[] {
  return PRODUCTS.filter(p => p.isPublished);
}

export function getFeaturedProducts(): Product[] {
  return PRODUCTS.filter(p => p.isPublished && p.isFeatured);
}

export function getProductBySlug(slug: string): Product | undefined {
  return PRODUCTS.find(p => p.slug === slug);
}

export function getProductsByCategory(category: string): Product[] {
  if (!category || category === 'all') return getAllProducts();
  return PRODUCTS.filter(p => p.isPublished && p.category.toLowerCase() === category.toLowerCase());
}

export function getRelatedProducts(currentSlug: string, category: string, limit = 4): Product[] {
  return PRODUCTS
    .filter(p => p.isPublished && p.slug !== currentSlug && p.category === category)
    .slice(0, limit);
}
